package codegen

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// ──────────────────────────────────────────────────────────────────────
// Default mocks for every service a frontend's generated TypeScript covers
// ──────────────────────────────────────────────────────────────────────
//
// The entity fixtures cover generated CRUD only. Every other RPC — a custom
// read, a search, a stream, any RPC of a contract VENDORED from another repo
// and generated by its own buf template — answered Unimplemented in mock mode
// until someone hand-wrote a scenario handler for it.
//
// The values are not decided here. @reliantlabs/forge-web-runtime's
// serviceDefaults(Service) builds each response at runtime from the
// service's descriptor, which protoc-gen-es embeds — protovalidate options
// included — in every `_pb.ts`. So the generator needs no proto descriptors
// at all, only the answer to "which services does this frontend have
// TypeScript for?", and the place that answers it for every contract alike is
// the generated TypeScript itself: whatever wrote src/gen (forge's buf step, a
// project's own template for a vendored contract), its services are there.

// TSService is one Connect service exported by a protoc-gen-es module.
type TSService struct {
	// TypeName is the fully-qualified proto name, e.g. "acme.v1.BillingService".
	TypeName string
	// Export is the module's exported GenService constant, e.g. "BillingService".
	Export string
	// ImportPath is the module's path under the gen directory, slash-separated
	// and without its extension, e.g. "acme/v1/billing_pb".
	ImportPath string
	// FirstMethod is the localName of the service's first RPC ("getInvoice"),
	// used in the generated module's usage note; empty for a service with none.
	FirstMethod string
}

// tsServiceRE matches protoc-gen-es (v2) service exports:
//
//	/**
//	 * ...
//	 * @generated from service acme.v1.BillingService
//	 */
//	export const BillingService: GenService<{
//
// Further doc-comment lines (`@deprecated`) may sit between the tag and the
// comment's end.
var tsServiceRE = regexp.MustCompile(`@generated from service ([A-Za-z_][A-Za-z0-9_.]*)[ \t]*\r?\n(?:[ \t]*\*[^\n]*\n)*?[ \t]*\*/[ \t]*\r?\nexport const ([A-Za-z_$][A-Za-z0-9_$]*): GenService<\{`)

// tsMethodRE matches a method key of a GenService type literal.
var tsMethodRE = regexp.MustCompile(`(?m)^[ \t]+([A-Za-z_$][A-Za-z0-9_$]*): \{[ \t]*\r?\n[ \t]+methodKind:`)

// ScanTSServices lists every service exported by the `*_pb.ts` modules under
// genDir (recursively), sorted by type name. A missing genDir — a frontend
// whose stubs have not been generated yet — has none.
func ScanTSServices(genDir string) ([]TSService, error) {
	var out []TSService
	err := filepath.WalkDir(genDir, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			if path == genDir && os.IsNotExist(err) {
				return filepath.SkipAll
			}
			return err
		}
		if d.IsDir() || !strings.HasSuffix(d.Name(), "_pb.ts") {
			return nil
		}
		body, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(genDir, path)
		if err != nil {
			return err
		}
		importPath := strings.TrimSuffix(filepath.ToSlash(rel), ".ts")
		text := string(body)
		for _, m := range tsServiceRE.FindAllStringSubmatchIndex(text, -1) {
			svc := TSService{
				TypeName:   text[m[2]:m[3]],
				Export:     text[m[4]:m[5]],
				ImportPath: importPath,
			}
			if first := tsMethodRE.FindStringSubmatch(text[m[1]:]); first != nil {
				svc.FirstMethod = first[1]
			}
			out = append(out, svc)
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("scan %s for services: %w", genDir, err)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].TypeName < out[j].TypeName })
	return out, nil
}

// ServiceDefaultsModule is one generated `src/mocks/services/<Slug>_gen.ts`.
type ServiceDefaultsModule struct {
	TSService
	// Slug is the file name without `_gen.ts`: the export in kebab case,
	// package-qualified when another package exports the same name.
	Slug string
	// Const is the exported defaults constant: `billingServiceDefaults`, or
	// `acmeV1BillingServiceDefaults` when qualified.
	Const string
}

// PlanServiceDefaults names one module per service. Services whose export
// names collide across packages (two `TelemetryService`s) are all qualified
// by package, so neither file name depends on the other's arrival order.
func PlanServiceDefaults(services []TSService) []ServiceDefaultsModule {
	count := map[string]int{}
	for _, s := range services {
		count[PascalToKebab(s.Export)]++
	}
	out := make([]ServiceDefaultsModule, 0, len(services))
	for _, s := range services {
		slug := PascalToKebab(s.Export)
		constName := lowerFirstRune(s.Export) + "Defaults"
		if count[slug] > 1 {
			pkg := strings.TrimSuffix(s.TypeName, "."+s.Export)
			parts := strings.FieldsFunc(pkg, func(r rune) bool { return r == '.' || r == '_' })
			slug = strings.ToLower(strings.Join(parts, "-")) + "-" + slug
			var camel strings.Builder
			for i, p := range parts {
				if i == 0 {
					camel.WriteString(strings.ToLower(p))
					continue
				}
				camel.WriteString(strings.ToUpper(p[:1]) + p[1:])
			}
			constName = camel.String() + s.Export + "Defaults"
		}
		out = append(out, ServiceDefaultsModule{TSService: s, Slug: slug, Const: constName})
	}
	return out
}

func lowerFirstRune(s string) string {
	if s == "" {
		return s
	}
	return strings.ToLower(s[:1]) + s[1:]
}
